pub open spec fn rmi_mec_set_shared_spec(mecid: Bits64, result: Result<(), RmiStatusCode>, old_s: S, new_s: S) -> bool {
    (mecid > ImplFeatures(old_s).max_mecid ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (MecState(old_s, mecid) != MEC_STATE_PRIVATE_UNASSIGNED ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (result.is_Ok() ==> MecState(new_s, mecid) == MEC_STATE_SHARED)
}

pub open spec fn rmi_rtt_aux_map_protected_spec(rd: Address, ipa: Address, index: UInt64, result: Result<(), RmiStatusCode>, state: RmiRttEntryState, ripas: RmiRipas, old_s: S, new_s: S) -> bool {
    let realm = RealmAt(old_s, rd);
    let walk_pri = RttWalk_(old_s, rd, ipa, RMM_RTT_PAGE_LEVEL as int);
    let walk_aux = RttWalk_(old_s, rd, ipa, RMM_RTT_PAGE_LEVEL as int);
    let entry_idx = RttEntryIndex(old_s, ipa, walk_aux.level as int);
    let entry_pri = RttEntryAt(old_s, RttWalk_(old_s, realm, ipa, RMM_RTT_PAGE_LEVEL as int).rtt_addr, entry_idx as int);
    let entry_aux = RttEntryAt(old_s, RttWalk_(old_s, realm, ipa, RMM_RTT_PAGE_LEVEL as int).rtt_addr, entry_idx as int);
    (!AddrIsGranuleAligned(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!PaIsDelegable(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!GranuleAt(old_s, rd).state == RD ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!AddrIsGranuleAligned(old_s, ipa) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!AddrIsProtected(old_s, ipa, realm) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (ImplFeatures(old_s).rtt_tree_per_plane == RMM_FEATURE_FALSE || index == RMM_RTT_TREE_PRIMARY || index > ImplFeatures(old_s).num_aux_planes ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (walk_pri.level != RMM_RTT_PAGE_LEVEL || walk_pri.valid == RMM_FALSE ==> ResultEqual(result, RMI_ERROR_RTT))
    && (walk_pri.level != RMM_RTT_PAGE_LEVEL || walk_pri.valid == RMM_FALSE ==> ResultEqual(result, RMI_ERROR_RTT))
    && (walk_aux.level != RMM_RTT_PAGE_LEVEL || walk_aux.valid == RMM_FALSE ==> ResultEqual(result, RMI_ERROR_RTT_AUX))
    && (walk_aux.level != RMM_RTT_PAGE_LEVEL || walk_aux.valid == RMM_FALSE ==> ResultEqual(result, RMI_ERROR_RTT_AUX))
    && (ResultEqual(result, RMI_ERROR_RTT) ==> (entry_pri.state == ASSIGNED || entry_pri.state == ASSIGNED_DEV || entry_pri.state == ASSIGNED_VSMMU))
    && (ResultEqual(result, RMI_ERROR_RTT) && entry_pri.state == ASSIGNED ==> RipasToRmi(old_s, entry_pri.ripas) != RMI_RAM)
    && (ResultEqual(result, RMI_ERROR_RTT) && entry_pri.state == ASSIGNED_DEV ==> RipasToRmi(old_s, entry_pri.ripas) != RMI_DEV)
    && (ResultEqual(result, RMI_ERROR_RTT_AUX) ==> entry_aux.state == AUX_DESTROYED)
    && (ResultEqual(result, RMI_ERROR_RTT_AUX) ==> walk_aux.level < walk_pri.level)
    && (result.is_Ok() ==> entry_aux.state == ASSIGNED)
    && (result.is_Ok() ==> entry_aux.attr_prot == entry_pri.attr_prot)
    && (result.is_Ok() ==> entry_aux.sh == entry_pri.sh)
}

pub open spec fn rmi_rtt_aux_unmap_unprotected_spec(rd: Address, ipa: Address, index: UInt64, result: Result<(), RmiStatusCode>, top: Address, old_s: S, new_s: S) -> bool {
    let realm = RealmAt(old_s, rd);
    let walk = RttWalk_(old_s, rd, ipa, realm.rtt_level_start as int);
    let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
    let walk_top = RttSkipNonLiveEntries(old_s, RttAt(old_s, walk.rtt_addr), walk.level, ipa);
    let rtte = RttEntryAt(old_s, RttAt(old_s, walk.rtt_addr), entry_idx);

    (!AddrIsGranuleAligned(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!PaIsDelegable(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!GranuleAt(old_s, rd).state == RD ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!AddrIsRttLevelAligned(old_s, ipa, realm.rtt_level_start as int) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && ((ipa as int) >= pow2(realm.ipa_width as int) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (AddrIsProtected(old_s, ipa, realm) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (realm.rtt_tree_per_plane == RMM_FEATURE_FALSE ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (index == RMM_RTT_TREE_PRIMARY ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (index > realm.num_aux_planes ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (rtte.state == UNASSIGNED_NS ==> result.is_Ok())
    && (result.is_Ok() ==> top == walk_top)
    && (result.is_Ok() ==> GranuleAt(new_s, rd).state == RD)
    && (result.is_Ok() ==> GranuleAt(new_s, ipa).state == UNDELEGATED)
}

pub open spec fn rmi_rtt_create_spec(rd: Address, rtt: Address, ipa: Address, level: Int64, result: Result<(), RmiStatusCode>, old_s: S, new_s: S) -> bool {
    // Failure: rd not aligned to granule
    (!AddrIsGranuleAligned(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: rd not delegable
    (!PaIsDelegable(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: Granule at rd not in RD state
    (GranuleAt(old_s, rd).state != RD ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: level not valid or is starting level
    (!RttLevelIsValid(old_s, RealmAt(old_s, rd), level) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: ipa not aligned to parent entry size
    (!AddrIsAligned(old_s, ipa, RttLevelSize(old_s, level - 1 as int)) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: ipa outside IPA space
    (!AddrIsWithin(old_s, ipa, 0, pow2(old_s, RealmAt(old_s, rd).ipa_width as int)) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: rtt not aligned to granule
    (!AddrIsGranuleAligned(old_s, rtt) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: rtt not delegable in DRAM
    (!PaIsDelegable(old_s, rtt) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: Granule at rtt not in DELEGATED state
    (GranuleAt(old_s, rtt).state != DELEGATED ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: LPA2 not supported and rtt >= 2^48
    (!Equal(old_s, RealmAt(old_s, rd).feat_lpa2, FEATURE_TRUE) && (rtt as int) >= (1u64 << 48) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: RTT walk ends below level - 1
    (RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).level < (level - 1) as int ==> ResultEqual(result, RMI_ERROR_RTT))
    // Failure: RTT entry found is already in TABLE state
    (RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.state == TABLE ==> ResultEqual(result, RMI_ERROR_RTT))
    // Success: Granule at rtt is in RTT state
    (GranuleAt(new_s, rtt).state == RTT)
    // Success: RTT entry found by walk is in TABLE state
    (RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.state == TABLE)
    // Success: That RTT entry points to rtt
    (RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr == rtt)
    // Success: If ipa is Protected IPA, every entry in new RTT has RIPAS value that parent had
    (AddrIsProtected(old_s, ipa, RealmAt(old_s, rd)) ==> (forall rtte: RmmRttEntry |
        let rtte_idx: int = RttEntryIndex(old_s, ipa, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).level as int);
        let rtte: RmmRttEntry = RttEntryAt(old_s, RttAt(old_s, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr), rtte_idx);
        let parent_rtte: RmmRttEntry = RttFold(old_s, RttAt(old_s, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr));
        rtte.ripas == parent_rtte.ripas))
    // Success: Every entry in new RTT has state that parent had
    (forall rtte: RmmRttEntry |
        let rtte_idx: int = RttEntryIndex(old_s, ipa, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).level as int);
        let rtte: RmmRttEntry = RttEntryAt(old_s, RttAt(old_s, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr), rtte_idx);
        let parent_rtte: RmmRttEntry = RttFold(old_s, RttAt(old_s, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr));
        rtte.state == parent_rtte.state)
    // Success: If parent was not UNASSIGNED/UNASSIGNED_NS, entries map contiguous output range starting at parent's address
    (forall rtte: RmmRttEntry |
        let rtte_idx: int = RttEntryIndex(old_s, ipa, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).level as int);
        let rtte: RmmRttEntry = RttEntryAt(old_s, RttAt(old_s, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr), rtte_idx);
        let parent_rtte: RmmRttEntry = RttFold(old_s, RttAt(old_s, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).rtte.addr));
        (parent_rtte.state != UNASSIGNED && parent_rtte.state != UNASSIGNED_NS) ==> (
            let parent_addr: Address = parent_rtte.addr;
            let parent_level: int = RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).level as int;
            let entry_level: int = RttEntryIndex(old_s, ipa, RttWalk(old_s, RealmAt(old_s, rd), ipa, level - 1 as int, RMM_RTT_TREE_PRIMARY).level as int);
            let entry_size: int = RttLevelSize(old_s, entry_level as int);
            let start_addr: Address = parent_addr;
            let end_addr: Address = start_addr + (entry_size as int) * (1u64 << (level - entry_level - 1) as int);
            AddrRangeIsWithin(old_s, start_addr, end_addr, start_addr, end_addr)))
}

pub open spec fn rmi_rtt_destroy_spec(rd: Address, ipa: Address, level: Int64, result: Result<(), RmiStatusCode>, rtt: Address, top: Address, old_s: S, new_s: S) -> bool {
    let realm = RealmAt(old_s, rd);
    let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
    let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
    let walk_top = RttSkipNonLiveEntries(old_s, RttAt(old_s, walk.rtt_addr), walk.level, ipa);
    let granule_at_rd = GranuleAt(old_s, rd);
    let granule_at_rtt = GranuleAt(old_s, rtt);
    let rtte = RttEntryAt(old_s, RttAt(old_s, walk.rtt_addr), entry_idx);
    let is_protected = AddrIsProtected(old_s, ipa, realm);
    let is_valid_level = RttLevelIsValid(old_s, realm, level) && level != old_s.RealmParams.rtt_level_start;
    let is_ipa_aligned = AddrIsRttLevelAligned(old_s, ipa, (level - 1) as int);
    let is_ipa_in_range = AddrIsWithin(old_s, ipa, 0, pow2(old_s.RealmParams.ipa_width as int) as Address);
    let is_rd_delegable = PaIsDelegable(old_s, rd);
    let is_rd_rd_state = granule_at_rd.state == RD;
    let is_walk_level_valid = walk.level >= (level - 1) as int;
    let is_walk_entry_table = rtte.state == TABLE;
    let is_target_rtt_live = RttIsLive(old_s, walk.rtt_addr);
    let is_ipa_aux = RttsAllProtectedEntriesRipas(old_s, walk.rtt_addr, walk.level, ipa, rtte.ripas);
    let is_rtt_unassigned = rtte.state == UNASSIGNED;
    let is_rtt_unassigned_ns = rtte.state == UNASSIGNED_NS;
    let is_rtt_ripas_destroyed = rtte.ripas == DESTROYED;
    let is_granule_delegated = granule_at_rtt.state == DELEGATED;
    let is_top_correct = top == walk_top;
    let is_rtt_correct = rtt == rtte.addr;
    (!is_valid_level ==> ResultEqual(result, RMI_ERROR_RTT))
    && (!is_ipa_aligned ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!is_ipa_in_range ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!is_rd_delegable ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!is_rd_rd_state ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!is_walk_level_valid ==> ResultEqual(result, RMI_ERROR_RTT))
    && (!is_walk_entry_table ==> ResultEqual(result, RMI_ERROR_RTT))
    && (is_walk_entry_table && is_target_rtt_live ==> ResultEqual(result, RMI_ERROR_RTT))
    && (is_walk_entry_table && is_ipa_aux ==> ResultEqual(result, RMI_ERROR_RTT))
    && (result.is_Ok() ==> (is_rtt_unassigned || is_rtt_unassigned_ns))
    && (result.is_Ok() ==> is_rtt_ripas_destroyed)
    && (result.is_Ok() ==> is_granule_delegated)
    && (result.is_Ok() ==> is_top_correct)
    && (result.is_Ok() ==> is_rtt_correct)
}

pub open spec fn rmi_rtt_fold_spec(rd: Address, ipa: Address, level: Int64, result: Result<(), RmiStatusCode>, rtt: Address, old_s: S, new_s: S) -> bool {
    // Failure: rd not aligned to granule size
    (!AddrIsGranuleAligned(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: rd not delegable
    (!PaIsDelegable(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: Granule at rd not in RD state
    (GranuleAt(old_s, rd).state != RD ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: level not valid or is starting level
    (!RttLevelIsValid(old_s, RealmAt(old_s, rd), level) ==> ResultEqual(result, RMI_ERROR_INPUT))
    (RttLevelIsStarting(old_s, RealmAt(old_s, rd), level) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: ipa not aligned to entry size at level-1
    (!AddrIsRttLevelAligned(old_s, ipa, (level - 1) as int) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: ipa outside IPA space
    (ipa >= pow2(old_s, RealmAt(old_s, rd).ipa_width as int) ==> ResultEqual(result, RMI_ERROR_INPUT))
    // Failure: RTT walk stops before level-1
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     walk.level != (level - 1) as int ==> ResultEqual(result, RMI_ERROR_RTT(walk.level)))
    // Failure: RTT entry not in TABLE state
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     RmmRttEntryState::TABLE != RttEntryAt(RttAt(old_s, walk.rtt_addr), RttEntryIndex(old_s, ipa, walk.level)).state ==> ResultEqual(result, RMI_ERROR_RTT(walk.level)))
    // Failure: Child RTT not homogeneous
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     !RttIsHomogeneous(old_s, RttAt(old_s, walk.rtt_addr)) ==> ResultEqual(result, RMI_ERROR_RTT(walk.level)))
    // Failure: ipa referenced by auxiliary RTT
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     AddrIsAuxRef(old_s, ipa, RealmAt(old_s, rd)) ==> ResultEqual(result, RMI_ERROR_RTT(walk.level)))

    // Success: result is Ok
    (result.is_Ok())
    // Success: rtt is the address of the folded RTT
    (rtt == walk.rtt_addr)
    // Success: parent RTT entry state set to folded entries' state
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
     let folded_state = RttEntryAt(RttAt(old_s, walk.rtt_addr), entry_idx).state;
     GranuleAt(new_s, walk.rtt_addr).state == folded_state)
    // Success: parent RTT entry output address set to folded entries' output address (if not UNASSIGNED/UNASSIGNED_NS)
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
     let folded_entry = RttEntryAt(RttAt(old_s, walk.rtt_addr), entry_idx);
     if folded_entry.state != UNASSIGNED && folded_entry.state != UNASSIGNED_NS {
         GranuleAt(new_s, walk.rtt_addr).addr == folded_entry.addr
     } else {
         true
     })
    // Success: parent RTT entry memory attributes set (interpreted for Protected/Unprotected)
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
     let folded_entry = RttEntryAt(RttAt(old_s, walk.rtt_addr), entry_idx);
     if folded_entry.state == ASSIGNED {
         let folded_attr = folded_entry.attr_prot;
         GranuleAt(new_s, walk.rtt_addr).attr_prot == folded_attr
     } else if folded_entry.state == ASSIGNED_NS {
         let folded_attr = folded_entry.attr_unprot;
         GranuleAt(new_s, walk.rtt_addr).attr_unprot == folded_attr
     } else {
         true
     })
    // Success: parent RTT entry stage 2 access permissions set (interpreted with indirect encoding or realm encoding)
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
     let folded_entry = RttEntryAt(RttAt(old_s, walk.rtt_addr), entry_idx);
     if folded_entry.state == ASSIGNED {
         GranuleAt(new_s, walk.rtt_addr).s2ap_indirect.base_index == folded_entry.s2ap_indirect.base_index
     } else if folded_entry.state == ASSIGNED_NS {
         GranuleAt(new_s, walk.rtt_addr).s2ap_indirect.base_index == folded_entry.s2ap_indirect.base_index
     } else {
         true
     })
    // Success: parent RTT entry RIPAS set (if ipa is Protected IPA)
    (let walk = RttWalk_(old_s, rd, ipa, (level - 1) as int);
     let entry_idx = RttEntryIndex(old_s, ipa, walk.level);
     let folded_entry = RttEntryAt(RttAt(old_s, walk.rtt_addr), entry_idx);
     if GranuleAccessPermitted(old_s, ipa, PAS_REALM) {
         GranuleAt(new_s, walk.rtt_addr).ripas == folded_entry.ripas
     } else {
         true
     })
    // Success: Granule that held folded RTT is in DELEGATED state
    (GranuleAt(new_s, walk.rtt_addr).state == DELEGATED)
}

pub open spec fn rmi_rtt_init_ripas_spec(rd: Address, base: Address, top: Address, result: Result<(), RmiStatusCode>, out_top: Address, old_s: S, new_s: S) -> bool {
    let realm_pre = RealmAt(old_s, rd);
    let walk = RttWalk_(old_s, rd, base, RMM_RTT_PAGE_LEVEL as int);
    let walk_level = walk.level as int;
    let rtte = RttAt(old_s, walk.rtt_addr);
    let walk_top = RttSkipEntriesIfNotState(old_s, RttAt(old_s, walk.rtt_addr), walk_level, base, top, RmmRttEntryState::UNASSIGNED);
    (!AddrIsGranuleAligned(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!PaIsDelegable(old_s, rd) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!GranuleAt(old_s, rd).state == RD ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!realm_pre.state == REALM_NEW ==> ResultEqual(result, RMI_ERROR_REALM))
    && (top <= base ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!AddrIsProtected(old_s, (top - RmmGranuleSize) as Address, realm_pre) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (!AddrIsRttLevelAligned(old_s, base, walk_level) ==> ResultEqual(result, RMI_ERROR_RTT(walk_level)))
    && (!rtte.state == UNASSIGNED ==> ResultEqual(result, RMI_ERROR_RTT(walk_level)))
    && (!AddrIsGranuleAligned(old_s, top) ==> ResultEqual(result, RMI_ERROR_INPUT))
    && (base == walk_top ==> ResultEqual(result, RMI_ERROR_RTT(walk_level)))
    && (result.is_Ok() ==> out_top == walk_top)
    && (result.is_Ok() ==> new_s.realm.measurements[0] == old_s.realm.measurements[0])
}

pub open spec fn rmi_rtt_set_s2ap_spec(rd: Address, rec_ptr: Address, base: Address, top: Address, result: Result<(), RmiStatusCode>, out_top: Address, rtt_tree: UInt64, old_s: S, new_s: S) -> bool {
    let realm = RealmAt(old_s, rd);
    let rec = RecAt(old_s, rec_ptr);
    let not_aligned = RttWalkAnyNotAligned(old_s, realm, base, top, RMM_RTT_PAGE_LEVEL as int);
    let granule_at_rd = GranuleAt(old_s, rd);
    let granule_at_rec = GranuleAt(old_s, rec_ptr);
    let rec_state = RecState(old_s, rec);
    let rec_owner = RecOwner(old_s, rec);
    let rec_s2ap_addr = RecS2apAddr(old_s, rec);
    let rec_s2ap_top = RecS2apTop(old_s, rec);
    let rec_s2ap_overlay_index = RecS2apOverlayIndex(old_s, rec);
    let rtt_tree_index = RttTreeIndex(old_s, realm, rtt_tree);
    let rtt_tree_entries = RttEntries(old_s, realm, rtt_tree);
    let rtt_level_start = RealmRttLevelStart(old_s, realm);
    let rtt_num_start = RealmRttNumStart(old_s, realm);
    let rtt_level = RttLevel(old_s, realm, rtt_tree_entries, not_aligned.index);
    let rtt_entry = RttEntryAt(old_s, rtt_tree_entries, not_aligned.index);
    let rtt_entry_addr = RttEntryAddr(old_s, rtt_tree_entries, not_aligned.index);
    let rtt_entry_state = RttEntryState(old_s, rtt_tree_entries, not_aligned.index);
    let rtt_entry_attr_prot = RttEntryAttrProt(old_s, rtt_tree_entries, not_aligned.index);
    let rtt_entry_attr_unprot = RttEntryAttrUnprot(old_s, rtt_tree_entries, not_aligned.index);
    let rtt_entry_sh = RttEntrySh(old_s, rtt_tree_entries, not_aligned.index);
    let rtt_entry_s2ap_direct = RttEntryS2apDirect(old_s, rtt_tree_entries, not_aligned.index);
