pub open spec fn rmi_vdev_aux_count_spec(pdev_flags: Bits64, vdev_flags: Bits64, result: Result<(), RmiStatusCode>, aux_count: UInt64, old_s: S, new_s: S) -> bool {
    (!ResultEqual(result, RMI_ERROR_NOT_SUPPORTED) ==> (impl_features(old_s).feat_da == RMM_FEATURE_TRUE))
    && (result.is_Ok() ==> (aux_count == PdevAuxCount(old_s, RmiPdevFlagsDecode(old_s, pdev_flags))))
    && (result.is_Ok() ==> (aux_count == VdevAuxCount(old_s, RmiPdevFlagsDecode(old_s, pdev_flags), RmiVdevFlagsDecode(old_s, vdev_flags))))
    && (result.is_Ok() ==> (new_s == old_s))
}

pub open spec fn rsi_attestation_token_continue_spec(addr: Address, offset: UInt64, size: UInt64, result: RsiCommandReturnCode, len: UInt64, old_s: S, new_s: S) -> bool {
    let realm = CurrentRealm(old_s);
    let rec = CurrentRec(old_s);
    let walk = RttWalk_(old_s, realm as int, addr as int, RMM_RTT_PAGE_LEVEL as int);
    let granule_size = RMM_GRANULE_SIZE as int;
    let is_aligned = AddrIsAligned(old_s, addr, granule_size);
    let is_protected = AddrIsProtected(old_s, addr, realm);
    let ripas_empty = (walk.level as int) == 0 && (walk.rtte.ripas == RmmRipas::EMPTY);
    let offset_overflow = offset >= granule_size;
    let sum_overflow = (offset as int) + (size as int) < (offset as int);
    let sum_exceeds = (offset as int) + (size as int) > granule_size;
    let attest_in_progress = (old_s.rec.attest_state == RmmRecAttestState::ATTEST_IN_PROGRESS);
    let attest_complete = (new_s.rec.attest_state == RmmRecAttestState::NO_ATTEST_IN_PROGRESS);
    let token_complete = (result == RSI_SUCCESS);
    let token_incomplete = (result == RSI_INCOMPLETE);
    let token_failed_unknown = (result == RSI_ERROR_UNKNOWN);
    (is_aligned ==> (result == RSI_ERROR_INPUT))
    && (is_protected ==> (result == RSI_ERROR_INPUT))
    && (ripas_empty ==> (result == RSI_ERROR_INPUT))
    && (offset_overflow ==> (result == RSI_ERROR_INPUT))
    && (sum_overflow ==> (result == RSI_ERROR_INPUT))
    && (sum_exceeds ==> (result == RSI_ERROR_INPUT))
    && (!attest_in_progress ==> (result == RSI_ERROR_STATE))
    && (token_complete ==> (attest_complete))
    && (token_incomplete ==> (result == RSI_INCOMPLETE))
    && (token_failed_unknown ==> (result == RSI_ERROR_UNKNOWN))
    && (result == RSI_SUCCESS ==> (len <= size))
}

pub open spec fn rsi_attestation_token_init_spec(challenge_0: Bits64, challenge_1: Bits64, challenge_2: Bits64, challenge_3: Bits64, challenge_4: Bits64, challenge_5: Bits64, challenge_6: Bits64, challenge_7: Bits64, result: RsiCommandReturnCode, size: UInt64, old_s: S, new_s: S) -> bool {
    (result == RSI_SUCCESS ==> (new_s.CurrentRec().attest_state == ATTEST_IN_PROGRESS && new_s.CurrentRec().attest_challenge == [challenge_0, challenge_1, challenge_2, challenge_3, challenge_4, challenge_5, challenge_6, challenge_7] && size == AttestationTokenMaxSize(old_s, old_s.CurrentRealm())))
}

pub open spec fn rsi_measurement_read_spec(index: UInt64, result: RsiCommandReturnCode, value_0: Bits64, value_1: Bits64, value_2: Bits64, value_3: Bits64, value_4: Bits64, value_5: Bits64, value_6: Bits64, value_7: Bits64, old_s: S, new_s: S) -> bool {
    (index > 4 ==> result == RSI_ERROR_INPUT)
    && (result == RSI_SUCCESS ==> (
        let realm = CurrentRealm(old_s);
        let hash_algo = realm.hash_algo;
        let measurement = realm.measurements[index as int];
        let encoded = RealmMeasurementEncode(old_s, measurement);
        (hash_algo == RMM_HASH_SHA_256 ==> (
            value_0 == encoded[0]
            && value_1 == encoded[1]
            && value_2 == encoded[2]
            && value_3 == encoded[3]
            && value_4 == 0
            && value_5 == 0
            && value_6 == 0
            && value_7 == 0
        ))
        && (hash_algo == RMM_HASH_SHA_512 ==> (
            value_0 == encoded[0]
            && value_1 == encoded[1]
            && value_2 == encoded[2]
            && value_3 == encoded[3]
            && value_4 == encoded[4]
            && value_5 == encoded[5]
            && value_6 == encoded[6]
            && value_7 == encoded[7]
        ))
    ))
}

pub open spec fn rsi_vdev_get_info_spec(vdev_id: Bits64, addr: Address, result: RsiCommandReturnCode, old_s: S, new_s: S) -> bool {
    let realm = CurrentRealm(old_s);
    let vdev = VdevFromVdevId(old_s, realm, vdev_id);
    let pdev = PdevAt(old_s, vdev.pdev);
    let cfg = RsiVdevInfoAt(old_s, addr);
    let walk = RttWalk(old_s, realm, addr, RMM_RTT_PAGE_LEVEL as int, RMM_RTT_TREE_PRIMARY as int);

    (!((ImplFeatures(old_s).feat_da == RMM_FEATURE_TRUE) && (ImplFeatures(old_s).feat_ats == RMM_FEATURE_TRUE)) ==> result == RSI_ERROR_STATE)
    && ((vdev_id != VdevFromVdevId(old_s, realm, vdev_id).vdev_id) ==> result == RSI_ERROR_INPUT)
    && (!AddrIsAligned(old_s, addr, 512) ==> result == RSI_ERROR_INPUT)
    && (!AddrIsProtected(old_s, addr, realm) ==> result == RSI_ERROR_INPUT)
    && (RmmRipas(old_s, addr) == RMM_RIPAS_EMPTY ==> result == RSI_ERROR_INPUT)
    && (result == RSI_SUCCESS ==> (cfg.hash_algo == pdev.hash_algo) && (cfg.p2p_enabled == PdevFlags(old_s, pdev).p2p) && (cfg.p2p_bound == VdevAt(old_s, addr).p2p_bound) && (cfg.p2p_peer == VdevAt(old_s, addr).p2p_peer) && (VdevAttestInfoEqual1(VdevAttestInfoEqual1(old_s, vdev.vdev_attest_info_1, vdev.vdev_attest_info_2), cfg) == true) && (cfg.state == VdevAt(old_s, addr).vdev_state)))
}

pub open spec fn rsi_vdev_validate_mapping_spec(vdev_id: Bits64, ipa_base: Address, ipa_top: Address, pa_base: Address, flags: RsiDevMemFlags, lock_nonce: UInt64, meas_nonce: UInt64, report_nonce: UInt64, result: RsiCommandReturnCode, new_ipa_base: Address, response: RsiResponse, old_s: S, new_s: S) -> bool {
    (!((ImplFeatures(old_s).feat_da == RMM_FEATURE_TRUE) && (VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).state == VDEV_LOCKED) && (VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).state == VDEV_STARTED)) ==> result == RSI_ERROR_INPUT)
    && (!((AddrIsGranuleAligned(old_s, ipa_base)) && (AddrIsGranuleAligned(old_s, ipa_top)) && (AddrIsGranuleAligned(old_s, pa_base)) && (ipa_base < ipa_top) && (AddrIsWithin(old_s, ipa_base, CurrentRealm(old_s).rtt_base[0], CurrentRealm(old_s).rtt_base[0] + (1u64 << (CurrentRealm(old_s).ipa_width as int)))))) ==> result == RSI_ERROR_INPUT)
    && (!((lock_nonce == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).attest_info.lock_nonce as u64) && (meas_nonce == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).meas_digest[0]) && (report_nonce == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).report_digest[0]))) ==> result == RSI_ERROR_DEVICE)
    && ((ImplFeatures(old_s).feat_da == RMM_FEATURE_TRUE) && (VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).state == VDEV_LOCKED) && (VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).state == VDEV_STARTED) && (AddrIsGranuleAligned(old_s, ipa_base)) && (AddrIsGranuleAligned(old_s, ipa_top)) && (AddrIsGranuleAligned(old_s, pa_base)) && (ipa_base < ipa_top) && (AddrIsWithin(old_s, ipa_base, CurrentRealm(old_s).rtt_base[0], CurrentRealm(old_s).rtt_base[0] + (1u64 << (CurrentRealm(old_s).ipa_width as int)))) && (lock_nonce == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).attest_info.lock_nonce as u64) && (meas_nonce == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).meas_digest[0]) && (report_nonce == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).report_digest[0])) ==> (result == RSI_SUCCESS) && (new_ipa_base == VdevFromVdevId(old_s, CurrentRealm(old_s), vdev_id).dev_mem_addr) && (response == RecDevMemResponseToRsi(old_s, CurrentRec(old_s))))
}

pub open spec fn rsi_version_spec(req: RsiInterfaceVersion, result: RsiCommandReturnCode, lower: RsiInterfaceVersion, higher: RsiInterfaceVersion, old_s: S, new_s: S) -> bool {
    (result == RSI_ERROR_INPUT ==> (
        (VersionEqualRsi(lower, req) ==> VersionEqualRsi(higher, req))
        || (lower.major < req.major || (lower.major == req.major && lower.minor < req.minor))
    ))
    && (result == RSI_SUCCESS ==> (
        VersionEqualRsi(lower, req) && VersionEqualRsi(higher, RsiVersionHighest(old_s))
    ))
    && (result != RSI_SUCCESS ==> (
        (lower.major < req.major || (lower.major == req.major && lower.minor < req.minor))
    ))
    && (result == RSI_SUCCESS ==> (
        VersionEqualRsi(lower, req) && VersionEqualRsi(higher, RsiVersionHighest(old_s))
    ))
}

pub open spec fn rsi_vsmmu_get_info_spec(addr: Address, result: RsiCommandReturnCode, top: Address, old_s: S, new_s: S) -> bool {
    let realm = CurrentRealm(old_s);
    let walk = RttWalk(old_s, realm, addr, RMM_RTT_PAGE_LEVEL as int, RMM_RTT_TREE_PRIMARY as int);
    (!((addr as int) % (RMM_GRANULE_SIZE as int) != 0) ==> result == RSI_ERROR_INPUT)
    && (!AddrIsProtected(old_s, addr, realm) ==> result == RSI_ERROR_INPUT)
    && (!RttEntryStateToRmi(old_s, RttEntryAt(old_s, RttAt(old_s, addr), walk.index as int)).state == RMI_ASSIGNED_VSMMU ==> result == RSI_ERROR_INPUT)
    && (!AddrIsWithin(old_s, addr, RttAt(old_s, addr), walk.rtt_addr, RttAt(old_s, addr), walk.rtt_addr + (RttLevelSize(old_s, RMM_RTT_PAGE_LEVEL as int) as int)) ==> result == RSI_ERROR_INPUT)
    && (result == RSI_SUCCESS ==> top == RttAt(old_s, addr).reg_top)
    && (result == RSI_SUCCESS ==> AddrIsWithin(old_s, addr, RttAt(old_s, addr), walk.rtt_addr, RttAt(old_s, addr), walk.rtt_addr + (RttLevelSize(old_s, RMM_RTT_PAGE_LEVEL as int) as int)))
}
